const payload = $input.first().json;
const result = payload.data || payload;
const body = result.draft?.body || '';
const trace = result.trace || {};
const diagnostics = result.diagnostics || {};
const webhookBody = $node['Webhook'].json.body || {};
const violations = Array.isArray(result.violations) ? result.violations : [];
return [{
  json: {
    result,
    body,
    trace,
    diagnostics,
    violations,
    qualityPass: body.length >= Number(webhookBody.minChars || 800) && violations.length === 0,
    saveRequest: {
      requestId: webhookBody.requestId,
      actor: webhookBody.actor || 'n8n-novel-factory',
      payload: {
        workId: webhookBody.workId,
        chapterId: webhookBody.chapterId,
        chapterNumber: webhookBody.chapterNumber,
        volumeNumber: webhookBody.volumeNumber || 1,
        title: webhookBody.title || webhookBody.topic,
        body,
        status: webhookBody.generationStatus || 'first_draft',
        createIfMissing: webhookBody.createIfMissing !== false,
        metadata: {
          source: 'n8n.novel-factory-generate-quality-publish',
          contentbaseAction: 'generate-chapter',
          trace,
          diagnostics,
          contractUsed: result.contractUsed || null,
          nextAllowedActions: result.nextAllowedActions || []
        }
      }
    }
  }
}];
